sql.where:


    (
        c.road_address_name LIKE CONCAT('%', #{region}, '%') 
        OR c.address_name LIKE CONCAT('%', #{region}, '%')
    )


AND SUBSTRING_INDEX(c.address_name, ' ', 1) NOT IN (
    '서울', '대구', '대전', '부산', '울산', '광주', '세종'
)


    AND c.place_name LIKE CONCAT('%', #{place_name}, '%') 



    AND c.place_category_detail IN

        #{item}
